"""Exports a TinyLM as a self-contained Hugging Face model directory."""

import dataclasses
import inspect
import json
import pathlib
import typing

import safetensors.torch
from tokenizers import Tokenizer
from transformers import PreTrainedTokenizerFast

from tinylm import model
from tinylm.atomic import Staging

SPECIAL = {
    "pad_token": "<pad>",
    "unk_token": "<unk>",
    "bos_token": "<bos>",
    "eos_token": "<eos>",
    "mask_token": "<mask>",
}
TIED = "net.head.weight"
WRAPPER = '''

# --- Hugging Face wrapper (generated by tinylm.export) ---
from transformers import PretrainedConfig, PreTrainedModel  # noqa: E402
from transformers.modeling_outputs import (  # noqa: E402
    BaseModelOutput,
    CausalLMOutput,
)

FIELDS = {fields}


class TinyLMConfig(PretrainedConfig):
    """Hugging Face config mirroring Config."""

    model_type = "tinylm"
    attribute_map = {{"hidden_size": "d_model"}}

    def __init__(self, {signature}, **kwargs):
{assignments}
        kwargs["tie_word_embeddings"] = tie_embeddings
        super().__init__(**kwargs)


class TinyLMForCausalLM(PreTrainedModel):
    """Causal LM head over TinyLM."""

    config_class = TinyLMConfig
    _tied_weights_keys = {{"net.head.weight": "net.tok_emb.weight"}}

    def __init__(self, config):
        super().__init__(config)
        if not config.tie_embeddings:
            self._tied_weights_keys = {{}}
        values = {{name: getattr(config, name) for name in FIELDS}}
        self.net = TinyLM(Config(**values))
        self.post_init()

    def get_input_embeddings(self):
        return self.net.tok_emb

    def get_output_embeddings(self):
        return self.net.head

    def forward(self, input_ids, attention_mask=None, labels=None, **kwargs):
        logits = self.net(input_ids)
        loss = None
        if labels is not None:
            shifted = logits[:, :-1].reshape(-1, logits.shape[-1])
            loss = torch.nn.functional.cross_entropy(
                shifted, labels[:, 1:].reshape(-1), ignore_index=-100
            )
        return CausalLMOutput(loss=loss, logits=logits)


class TinyLMModel(TinyLMForCausalLM):
    """Encoder-style view for classifier heads (AutoModel).

    last_hidden_state has shape (batch, 1, d_model): the state at the last
    real token of each row. The attention mask marks real tokens; each row is
    re-packed so its real tokens come first, in order, which makes the result
    exact for left- or right-padded batches (this model is causal and has no
    padding mask of its own). Masks that are not 2-D, or rows with no real
    token, raise.
    """

    def forward(self, input_ids, attention_mask=None, **kwargs):
        if attention_mask is None:
            return BaseModelOutput(
                last_hidden_state=self.net.hidden(input_ids)[:, -1:]
            )
        if attention_mask.ndim != 2:
            raise ValueError("attention_mask must be 2-D (batch, length)")
        real = attention_mask.long()
        counts = real.sum(dim=1)
        if bool((counts == 0).any()):
            raise ValueError("a row has no tokens")
        order = torch.argsort(1 - real, dim=1, stable=True)
        packed = input_ids.gather(1, order)
        hidden = self.net.hidden(packed)
        index = (counts - 1).view(-1, 1, 1).expand(-1, 1, hidden.shape[-1])
        return BaseModelOutput(last_hidden_state=hidden.gather(1, index))
'''


class Error(Exception):
    """Raised when a model cannot be exported faithfully."""


def wrapper() -> str:
    """Generates the wrapper code from the fields of model.Config.

    Deriving it from the dataclass means a new model option can never be
    silently left out of an export.
    """
    default = model.Config()
    names = [f.name for f in dataclasses.fields(model.Config)]
    parts: list[str] = []
    for name in names:
        value: object = getattr(default, name)
        shown = (
            list(typing.cast("tuple[int, ...]", value))
            if isinstance(value, tuple)
            else value
        )
        parts.append(f"{name}={shown!r}")
    signature = ", ".join(parts)
    assignments = "\n".join(f"        self.{name} = {name}" for name in names)
    return WRAPPER.format(
        fields=repr(tuple(names)), signature=signature, assignments=assignments
    )


@dataclasses.dataclass(frozen=True, slots=True)
class Export:
    """A model and the tokenizer it was trained with.

    Attributes:
        net: Trained model.
        tok: Tokenizer whose vocabulary matches the model.
    """

    net: model.TinyLM
    tok: Tokenizer

    def write(
        self, target: pathlib.Path, max_parameters: int = model.PARAMETER_BUDGET
    ) -> None:
        """Writes a directory loadable with AutoModelForCausalLM.

        The directory is built in a sibling `.partial` folder and renamed on
        success, so a failed export leaves nothing behind.

        Raises:
            ValueError: If the model exceeds the parameter budget.
            Error: If the tokenizer and model vocabularies differ.
            FileExistsError: If target already exists.
        """
        model.check(self.net, max_parameters)
        if self.tok.get_vocab_size() != self.net.config.vocab_size:
            raise Error(
                f"tokenizer vocab {self.tok.get_vocab_size()} != "
                f"model vocab {self.net.config.vocab_size}"
            )
        config = self.net.config
        with Staging(target) as staged:
            (staged / "modeling_tinylm.py").write_text(
                inspect.getsource(model) + wrapper()
            )
            settings: dict[str, object] = {}
            for field in dataclasses.fields(config):
                value: object = getattr(config, field.name)
                settings[field.name] = (
                    list(typing.cast("tuple[int, ...]", value))
                    if isinstance(value, tuple)
                    else value
                )
            description: dict[str, object] = {
                "model_type": "tinylm",
                "architectures": ["TinyLMForCausalLM"],
                "auto_map": {
                    "AutoConfig": "modeling_tinylm.TinyLMConfig",
                    "AutoModel": "modeling_tinylm.TinyLMModel",
                    "AutoModelForCausalLM": "modeling_tinylm.TinyLMForCausalLM",
                },
                "tie_word_embeddings": config.tie_embeddings,
                **settings,
            }
            (staged / "config.json").write_text(
                json.dumps(description, indent=2) + "\n"
            )
            state = {
                f"net.{key}": value.detach().cpu().contiguous()
                for key, value in self.net.state_dict().items()
                if not (config.tie_embeddings and f"net.{key}" == TIED)
            }
            safetensors.torch.save_file(
                state, staged / "model.safetensors", metadata={"format": "pt"}
            )
            PreTrainedTokenizerFast(
                tokenizer_object=self.tok, **SPECIAL
            ).save_pretrained(staged)
